<script setup>
import {ref} from 'vue'
import {asset} from '../data'
import {locale,t} from '../i18n'
import {openModal,session} from '../session'
import {amount,dateTime} from '../utils/format.js'
import RequestState from '../components/ui/RequestState.vue'
import Skeleton from '../components/ui/Skeleton.vue'
import EmptyState from '../components/ui/EmptyState.vue'
import {invalidate,useRequest} from '../composables/useRequest.js'
import {getCharity,listMyDonations} from '../api/charity.js'
// Campaigns, channel totals and the 真實 donation history come from the shared 公益 module (admin 公益 → 公益项目 /
// 频道统计) through api/charity.js: listed projects only, by sort weight, in the current language (English fallback).
// The module runs in this page's memory (static mock): admin edits made elsewhere do not reach this page.
const slide=ref(0)
const banners=[["content.ui.weCareForEveryChildCaughtInTheDevastation",'409d2b38d3103f4f.jpg'],["content.ui.weHelpEndHunger",'474d7ad6e890e265.jpg'],["content.ui.weBringComputersAndEthernetNetworksToEveryCorner",'924f557a9a47fa15.jpg'],["content.ui.weProvideHopeInTimesOfDisaster",'bdb62b7ed08ba2ce.jpg'],["content.ui.weInvestInTheEducationalFutureOfCountriesIn",'d9bfaf5ec8022daa.webp'],["content.ui.weHelpPeopleWithDisabilitiesStartANewLife",'d6c929ab13ae70e6.jpg']]
const catalog=useRequest(()=>getCharity(locale.value),{key:()=>locale.value,tags:['charity']})
const history=useRequest(()=>session.loggedIn?listMyDonations(session.mode,locale.value):Promise.resolve([]),{key:()=>[session.loggedIn,session.mode,locale.value].join('|'),tags:['charity']})
function donate(p){openModal('donate',"charity.donations.columns.project",{name:p.title,symbol:'USDT',min:p.minDonation,max:p.maxDonation,projectId:p.projectId,onConfirm:()=>invalidate('charity')})}
</script>
<template>
<section class="charity-banner"><img :src="asset(banners[slide][1])" :alt="$t(banners[slide][0])"/><h1>{{ $t(banners[slide][0]) }}</h1><div class="carousel-dots"><button v-for="(b,i) in banners" :key="b[0]" :class="{active:slide===i}" :aria-label="$t('charity.slideLabel',{index:i+1,title:$t(b[0])})" :aria-pressed="slide===i" @click="slide=i"></button></div></section><section class="charity-intro"><h2 class="section-heading">{{ $t("charity.narrative.title") }}</h2><p>{{ $t("content.ui.connectGenerosityWithMeaningfulChangeAndBringHopeTo") }}</p></section><section class="container section-pad"><div class="section-row"><h2 class="section-heading">{{ $t("charity.donations.columns.project") }}</h2><span class="muted">{{ $t("charity.stats.title") }}</span></div><RequestState :status="catalog.status.value" :error="catalog.error.value" class="card" @retry="catalog.refresh"><template #loading><div class="three-cols"><div v-for="i in 3" :key="i" class="charity-card"><Skeleton class="charity-skeleton-cover"/><div class="charity-skeleton-body"><Skeleton width="80%" height="18px"/><Skeleton height="6px"/><Skeleton width="50%"/><Skeleton height="44px"/></div></div></div></template><div v-if="catalog.data.value?.projects.length" class="three-cols"><article v-for="p in catalog.data.value.projects" :key="p.projectId" class="charity-card"><img :src="p.image" :alt="p.title" loading="lazy"/><div><h3>{{ p.title }}</h3><p v-if="p.summary" class="muted charity-summary">{{ p.summary }}</p><div class="summary-line"><small>{{ $t("charity.campaigns.raisedLabel") }}</small><strong>{{ amount(p.raised) }} USDT</strong></div><div class="progress" role="progressbar" :aria-valuenow="p.progress" aria-valuemin="0" aria-valuemax="100" :aria-label="p.title"><span :style="{width:p.progress+'%'}"></span></div><div class="summary-line"><small>{{ $t("charity.campaigns.targetLabel") }}{{ amount(p.targetAmount) }} USDT</small><small>{{ p.progress }}%</small></div><p class="mini-label" style="margin-top:12px">{{ $t("charity.stats.peopleHelped") }}{{ amount(p.peopleHelped) }}</p><button class="primary-button wide-button" @click="donate(p)">{{ $t("charity.campaigns.donate") }}</button></div></article></div><EmptyState v-else class="card" :text="t('charity.campaigns.empty.title')" :hint="t('charity.campaigns.empty.desc')"/></RequestState></section><section class="container section-pad section-bordered"><div class="two-cols"><div><small class="mini-label">{{ $t("charity.stats.totalRaised") }}</small><p class="metric section-gap"><template v-if="catalog.data.value">{{ amount(catalog.data.value.totals.totalRaised) }}</template><Skeleton v-else inline width="200px"/> <small>{{ $t("USDT") }}</small></p></div><div><small class="mini-label">{{ $t("charity.stats.peopleHelped") }}</small><p class="metric section-gap"><template v-if="catalog.data.value">{{ amount(catalog.data.value.totals.peopleHelped) }}</template><Skeleton v-else inline width="160px"/> <small>{{ $t("promotion.progress.unit.REFERRAL") }}</small></p></div></div><div class="card section-gap"><h2>{{ $t("charity.donations.label") }}</h2><EmptyState v-if="!session.loggedIn" :text="t('charity.donations.signedOut.title')" :hint="t('charity.donations.signedOut.desc')"/><RequestState v-else :status="history.status.value" :error="history.error.value" @retry="history.refresh"><template #loading><div class="charity-history"><Skeleton v-for="i in 3" :key="i" height="44px"/></div></template><ul v-if="history.data.value?.length" class="charity-history"><li v-for="d in history.data.value" :key="d.donationId"><div><strong>{{ d.title }}</strong><small class="muted">{{ dateTime(d.createdAt,locale) }} · {{ d.donationId }}</small></div><div class="charity-history-amount"><strong>{{ amount(d.amount) }} {{ d.asset }}</strong><small class="muted">{{ $t("charity.donations.statusCompleted") }}</small></div></li></ul><EmptyState v-else :text="t('charity.donations.empty.title')" :hint="t('charity.donations.empty.desc')"/></RequestState></div></section><section class="container section-pad section-bordered"><h2 class="section-heading">{{ $t("charity.howItWorks.title") }}</h2><div class="four-cols section-gap"><div v-for="(s,i) in [&quot;charity.donations.columns.project&quot;,&quot;charity.donate.amountLabel&quot;,&quot;charity.donate.confirm.submit&quot;,&quot;charity.narrative.highlights.2.title&quot;]" :key="s"><p class="metric">0{{ $t(i+1) }}</p><h3 style="margin-top:20px">{{ $t(s) }}</h3></div></div></section>
</template>
<style scoped>.charity-skeleton-cover{aspect-ratio:1.6;height:auto;border-radius:0}.charity-skeleton-body{display:grid;gap:14px}.charity-summary{margin-bottom:12px;font-size:.8125rem;line-height:1.6}.charity-history{list-style:none;margin:16px 0 0;padding:0;display:grid;gap:8px}.charity-history li{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 0;border-top:1px solid var(--nt-border)}.charity-history li>div{display:grid;gap:4px;min-width:0}.charity-history li strong{overflow-wrap:anywhere}.charity-history-amount{text-align:right;flex-shrink:0}.carousel-dots button{box-sizing:content-box;border:8px solid transparent;background-clip:padding-box}.charity-banner{background:#16191a}@media(max-width:600px){.charity-banner h1{line-height:1.5}.carousel-dots{gap:0}}
</style>
